/**
 * Migrates the old '@nx/angular:ngrx' generator defaults within a `generators`
 * object (from either nx.json or a project.json). Mutates the object in place
 * and returns whether any changes were made.
 */
function migrateGenerators(
  generators: Record<string, any> | undefined
): boolean {
  if (!generators) {
    return false;
  }

  const flatOldDefaults = generators[OLD_FLAT_KEY];
  const nestedOldDefaults = generators[COLLECTION]?.[OLD_GENERATOR];

  if (!flatOldDefaults && !nestedOldDefaults) {
    return false;
  }

  // When both formats are present, the flat format takes precedence and the
  // migrated output is written in the flat format.
  const oldDefaults = flatOldDefaults ?? nestedOldDefaults;
  const oldWasFlat = flatOldDefaults !== undefined;

  // Remove the old defaults regardless of the format they were declared in.
  if (flatOldDefaults !== undefined) {
    delete generators[OLD_FLAT_KEY];
  }
  if (nestedOldDefaults !== undefined) {
    delete generators[COLLECTION][OLD_GENERATOR];
  }

  writeMigratedDefaults(
    generators,
    ROOT_STORE,
    pickOptions(oldDefaults, ROOT_STORE_OPTIONS),
    oldWasFlat
  );
  writeMigratedDefaults(
    generators,
    FEATURE_STORE,
    buildFeatureStoreOptions(oldDefaults),
    oldWasFlat
  );

  // If removing the old nested 'ngrx' entry left the '@nx/angular' collection
  // empty (and nothing new was written into it), drop the collection entirely.
  if (
    generators[COLLECTION] &&
    Object.keys(generators[COLLECTION]).length === 0
  ) {
    delete generators[COLLECTION];
  }

  return true;
}

function pickOptions(
  source: Record<string, any>,
  keys: readonly string[]
): Record<string, any> {
  const result: Record<string, any> = {};
  for (const key of keys) {
    if (key in source) {
      result[key] = source[key];
    }
  }
  return result;
}

function buildFeatureStoreOptions(
  source: Record<string, any>
): Record<string, any> {
  const result = pickOptions(source, FEATURE_STORE_OPTIONS);

  // The old 'module' option is renamed to 'parent'. When both are set, 'module'
  // takes precedence and its value becomes the migrated 'parent' value.
  if ('module' in source) {
    result.parent = source.module;
  } else if ('parent' in source) {
    result.parent = source.parent;
  }

  return result;
}

/**
 * Writes the migrated options onto the new generator key, choosing the flat or
 * nested format and merging into any existing defaults for that key (existing
 * user-set values take priority). Writes nothing when there are no options.
 */
function writeMigratedDefaults(
  generators: Record<string, any>,
  newGenerator: string,
  migrated: Record<string, any>,
  oldWasFlat: boolean
): void {
  const flatKey = `${COLLECTION}:${newGenerator}`;
  const nestedExisting = generators[COLLECTION]?.[newGenerator];
  const flatExisting = generators[flatKey];

  // Prefer whichever format the user already uses for the new key, so we merge
  // into it rather than creating a competing entry. Otherwise fall back to the
  // format the old defaults were declared in.
  let useNested: boolean;
  if (nestedExisting !== undefined) {
    useNested = true;
  } else if (flatExisting !== undefined) {
    useNested = false;
  } else {
    useNested = !oldWasFlat;
  }

  const existing = useNested ? nestedExisting : flatExisting;
  const merged = { ...migrated, ...(existing ?? {}) };

  // Don't create empty defaults for the new key.
  if (Object.keys(merged).length === 0) {
    return;
  }

  if (useNested) {
    generators[COLLECTION] ??= {};
    generators[COLLECTION][newGenerator] = merged;
  } else {
    generators[flatKey] = merged;
  }
